"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26363"],{1887(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.acao_quando_indeferido_divergente","status":422,"titulo":"O mesmo c\xf3digo de modalidade n\xe3o pode ter a\xe7\xf5es divergentes de vaga quando indeferido em ofertas distintas do processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.acao_quando_indeferido_divergente","requisitos":[],"oQueAconteceu":["Duas ofertas de curso do mesmo processo trazem a mesma modalidade de concorr\xeancia\\ncom a\xe7\xf5es de vaga diferentes para o caso de a inscri\xe7\xe3o ser indeferida. O processo\\ntrata a modalidade como uma s\xf3, qualquer que seja o curso; por isso a a\xe7\xe3o que se\\naplica ao candidato indeferido n\xe3o pode mudar de uma oferta para outra. A recusa\\nsai com **422** e nada foi gravado.","A a\xe7\xe3o vem do cadastro de modalidades e \xe9 copiada para o processo junto com o resto\\nda modalidade, todas as ofertas na mesma grava\xe7\xe3o. Por isso a diverg\xeancia n\xe3o nasce\\ndo que a pessoa digita: s\xf3 aparece se o cadastro mudou no meio da grava\xe7\xe3o."],"comoResolver":["Na defini\xe7\xe3o da distribui\xe7\xe3o de vagas, repita o pedido: as ofertas s\xe3o copiadas do\\ncadastro de novo. Se a recusa persistir, a gest\xe3o do cadastro de modalidades deve\\nconferir a a\xe7\xe3o de vaga ao indeferir da modalidade citada, que precisa ser uma s\xf3."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);